<?php
/** Optional test-only MU observer; configure SAVEQUERIES before WP bootstrap. */
if(!defined('ABSPATH')||!in_array(wp_get_environment_type(),['local','staging'],true))return;
$target=getenv('EXIN_BENCH_LOG');$id=$_SERVER['HTTP_X_EXIN_BENCH_ID']??'';
if(!$target||!preg_match('/^exin-[a-f0-9]{32}$/D',$id))return;
$usage=getrusage();$start=hrtime(true);
$guard_times=[];$guard_starts=[];
foreach(['woocommerce_product_get_price','woocommerce_product_get_sale_price','woocommerce_product_variation_get_price','woocommerce_product_variation_get_sale_price']as$hook){
 add_filter($hook,static function($price)use(&$guard_starts,$hook){if(class_exists('Exin\\BlackFriday\\Application\\FloorGuard',false)&&Exin\BlackFriday\Application\FloorGuard::$reading===0)$guard_starts[$hook][]=hrtime(true);return$price;},9998);
 add_filter($hook,static function($price)use(&$guard_starts,&$guard_times,$hook){if(class_exists('Exin\\BlackFriday\\Application\\FloorGuard',false)&&Exin\BlackFriday\Application\FloorGuard::$reading===0&&!empty($guard_starts[$hook])){$elapsed=(hrtime(true)-array_pop($guard_starts[$hook]))/1e6;$guard_times[$hook]['calls']=($guard_times[$hook]['calls']??0)+1;$guard_times[$hook]['ms']=($guard_times[$hook]['ms']??0)+$elapsed;}return$price;},10000);
}

add_action('shutdown',static function()use($target,$id,$usage,$start,&$guard_times){global$wpdb;$sql=array_column($wpdb->queries??[],0);$plugin=array_filter($wpdb->queries??[],static fn($q)=>str_contains($q[0],'exin_bf_')||str_contains($q[2]??'','Exin\\BlackFriday'));$u=getrusage();$cpu=1000*($u['ru_utime.tv_sec']+$u['ru_stime.tv_sec']-$usage['ru_utime.tv_sec']-$usage['ru_stime.tv_sec'])+($u['ru_utime.tv_usec']+$u['ru_stime.tv_usec']-$usage['ru_utime.tv_usec']-$usage['ru_stime.tv_usec'])/1000;$record=['guard_filter_windows'=>$guard_times,'id'=>$id,'version'=>defined('EXIN_BF_VERSION')?EXIN_BF_VERSION:null,'query_total'=>$wpdb->num_queries,'traced_queries'=>count($sql),'plugin_queries'=>count($plugin),'duplicate_queries'=>count($sql)-count(array_unique($sql)),'writes'=>count(preg_grep('/^(INSERT|UPDATE|DELETE|REPLACE)/i',$sql)),'locks'=>count(preg_grep('/GET_LOCK/',$sql)),'peak_bytes'=>memory_get_peak_usage(true),'mu_to_shutdown_ms'=>(hrtime(true)-$start)/1e6,'mu_to_shutdown_cpu_ms'=>$cpu,'trace_enabled'=>defined('SAVEQUERIES')&&SAVEQUERIES,'scope'=>'CPU/time from MU load to late WP shutdown; SQL complete only if SAVEQUERIES enabled before bootstrap; no SQL text or cookies recorded'];$groups=[];foreach($wpdb->queries??[]as$q){$caller=$q[2]??'';if(!str_contains($caller,'Exin\\BlackFriday'))continue;$groups[$caller]['queries']=($groups[$caller]['queries']??0)+1;$groups[$caller]['sql_ms']=($groups[$caller]['sql_ms']??0)+1000*$q[1];}$record['plugin_sql_callers']=$groups;file_put_contents($target,json_encode($record).PHP_EOL,FILE_APPEND|LOCK_EX);},PHP_INT_MAX);
